const DAYS_OF_WEEK = [
  { value: 0, label: 'Dom' },
  { value: 1, label: 'Seg' },
  { value: 2, label: 'Ter' },
  { value: 3, label: 'Qua' },
  { value: 4, label: 'Qui' },
  { value: 5, label: 'Sex' },
  { value: 6, label: 'Sáb' }
];

// Estado
const [availableDays, setAvailableDays] = useState<number[]>([]);

// Toggle de dia
const toggleDay = (dayValue: number) => {
  setAvailableDays(prev => 
    prev.includes(dayValue) 
      ? prev.filter(d => d !== dayValue)
      : [...prev, dayValue].sort((a, b) => a - b)
  );
};

// Renderização
{DAYS_OF_WEEK.map(day => (
  <button
    key={day.value}
    onClick={() => toggleDay(day.value)}
    className={availableDays.includes(day.value) ? 'selected' : ''}
  >
    {day.label}
  </button>
))}

